import hashlib
from pathlib import Path
root = Path('products/services/sqlite-repair/bespoke-inbound')
for path in sorted(root.rglob('*')):
    if not path.is_file() or not any(word in path.name for word in ('quote', 'control')):
        continue
    data = path.read_bytes()
    print(path, len(data), hashlib.sha256(data).hexdigest())
    if len(data) <= 5500:
        print(data.decode('utf-8'))
